  ui_story_31990601_1_dialog_content = "Registro de Ecología de Rediesel Wrench, Día 2.",
  ui_story_31990601_2_dialog_content = "La manada se va a buscar comida una vez más...",
  ui_story_31990601_3_dialog_content = "Desde que un cierto miembro de su grupo accidentalmente voló la cantina...",
  ui_story_31990601_4_dialog_content = "Todo Rediesel Wrench ha tenido que ir en expediciones de caza regulares como esta...",
  ui_story_31990601_5_dialog_content = "Hoy, su marca no es otra que...",
  ui_story_31990601_6_dialog_content = "Un raro y jugoso ejemplar conocido como PlayerName, que está intentando desesperadamente escapar del desierto.",
  ui_story_31990601_7_option_content = "¿...?",
  ui_story_31990601_8_dialog_content = "Parece que ha escapado del voraz Rediesel Wrench, realmente una hazaña notable.",
  ui_story_31990601_9_dialog_content = "¿Qué? N-No, solo estoy aquí por un trabajo...",
  ui_story_31990601_10_dialog_content = "Pensé que escuché una voz justo ahora... Sonaba como si alguien estuviera grabando un documental de naturaleza, así que vine a echar un vistazo.",
  ui_story_31990601_11_dialog_content = "No esperaba encontrarte aquí, Yingel... ¿Qué estás haciendo?",
  ui_story_31990601_12_dialog_content = "Como puedes ver, estoy observando a los Rediesel Wrench en su hábitat natural.",
  ui_story_31990601_13_dialog_content = "¿Hábitat natural? Pero eso es solo donde viven, ¿no es así?",
  ui_story_31990601_14_dialog_content = "Precisamente, lo que lo convierte en su hábitat. En cuanto a su forma de vida... creo que \"natural\" también es la manera perfecta de describirlo.",
  ui_story_31990601_15_dialog_content = "Sus patrones de vida pueden ofrecernos una visión de las vidas de nuestros primitivos antepasados aurorianos.",
  ui_story_31990601_16_dialog_content = "Eso es un poco exagerado...",
  ui_story_31990601_17_dialog_content = "Espera... ¿No estarás planeando hacer algo malo en su campamento, verdad?!",
  ui_story_31990601_18_dialog_content = "...",
  ui_story_31990601_19_dialog_content = "¿Realmente soy ese tipo de persona en tus ojos, PlayerName?",
  ui_story_31990601_20_dialog_content = "Rediesel Wrench puede carecer de estructura y disciplina, pero eso no los convierte en Eclipsites. Como tal, no tengo ninguna razón para apuntarles con mi arma.",
  ui_story_31990601_21_dialog_content = "E-Entonces... ¿Por qué estás realmente aquí?",
  ui_story_31990601_22_dialog_content = "No te estaba mintiendo. Realmente estoy en una misión de observación... Solo hice un pequeño desvío, eso es todo.",
  ui_story_31990601_23_dialog_content = "Originalmente, tenía la intención de inspeccionar el área entre las líneas del frente y el desierto, pero terminé cerca del campamento de Rediesel Wrench sin siquiera darme cuenta.",
  ui_story_31990601_24_dialog_content = "No iba a quedarme mucho tiempo, pero parece que el Desierto de Rediesel tiene un cierto encanto...",
  ui_story_31990601_25_dialog_content = "Conduje durante dos días, intentando irme, solo para encontrarme exactamente donde comencé.",
  ui_story_31990601_26_dialog_content = "...",
  ui_story_31990601_27_dialog_content = "¡Eso simplemente suena como que te perdiste!",
  ui_story_31990601_28_dialog_content = "No estoy perdido. Solo estoy ejecutando el Plan de Contingencia #43, eso es todo.",
  ui_story_31990601_29_dialog_content = "¿Estás seguro de que no te lo estás inventando?!",
  ui_story_31990601_30_dialog_content = "Para nada. De hecho, es la solución óptima, dado que un elfo del desierto me ha estado trayendo comida todo este tiempo.",
  ui_story_31990601_31_dialog_content = "Con su ayuda, puedo ejecutar el Plan de Contingencia #43 sin preocuparme por las restricciones de tiempo.",
  ui_story_31990601_32_dialog_content = "¡Espera, espera, espera!",
  ui_story_31990601_33_dialog_content = "¿Qué es un elfo del desierto?!",
  ui_story_31990601_34_dialog_content = "Una criatura amable y bien educada en forma de una niña pequeña. Claramente, debe estar viviendo con Rediesel Wrench por necesidad.",
  ui_story_31990601_35_dialog_content = "Entonces eso significa...",
  ui_story_31990601_36_dialog_content = "¡Solo estás sobreviviendo aquí porque has estado aprovechándote de las reservas de comida de Rediesel Wrench!",
  ui_story_31990601_37_dialog_content = "Como dije, eran regalos de un elfo del desierto y no de Rediesel...",
  ui_story_31990601_38_dialog_content = "¡Ahí estás, Señorita Rostro sin expresión!",
  ui_story_31990601_39_dialog_content = "Eso es...",
  ui_story_31990601_40_dialog_content = "¡Eh, PlayerName! ¿Qué estás haciendo aquí? ¿También estás viajando por el desierto?",
  ui_story_31990601_41_dialog_content = "Es...",
  ui_story_31990601_42_dialog_content = "(¡Espera! Por cómo se ve, Yingel aún no sabe que es la hermana menor de Sinsa...)",
  ui_story_31990601_43_dialog_content = "(Y como Yingel no lleva su uniforme... ¡Eve debe pensar que es solo otra viajera!)",
  ui_story_31990601_44_dialog_content = "(Si quiero mantener las cosas bajo control, ¡no puedo dejar que descubran las verdaderas identidades del otro!)",
  ui_story_31990601_45_dialog_content = "Eh... ¡Sí, eso es correcto! ¡En realidad estoy viajando con la señorita Pokerface aquí!",
  ui_story_31990601_46_dialog_content = "Como dije antes, no soy un viajero. El Desierto de Rediesel es mi hogar.",
  ui_story_31990601_47_dialog_content = "¡Oh, me alegra tanto que el Desierto de Rediesel te haga sentir como en casa, Señorita Pokerface!",
  ui_story_31990601_48_dialog_content = "Si ese es el caso, ¡entonces te va a encantar el almuerzo de hoy! ¡Ta-da!",
  ui_story_31990601_49_dialog_content = "¡Lagartos con pimiento fantasma extra picante!",
  ui_story_31990601_50_dialog_content = "Ahí está... ¡La verdadera razón por la que todos se alejan del desierto de Rediesel!",
  ui_story_31990601_51_dialog_content = "<size=30>¿Esto... realmente está destinado a ser comido? Como pensé, este lugar es para temer... Pero...</size>",
  ui_story_31990601_52_dialog_content = "Gracias. Como nativo del Desierto de Rediesel, naturalmente amo esta delicia local.",
  ui_story_31990601_53_dialog_content = "Tu regalo es muy apreciado. No puedo esperar para comer este maravilloso plato.",
  ui_story_31990601_54_dialog_content = "¡Adelante! Incluso traje más, ¡si aún tienes hambre después!",
  ui_story_31990601_55_dialog_content = "Yo... creo que uno es más que suficiente.",
  ui_story_31990601_56_dialog_content = "Um... Si no estás seguro de cómo comerlo, puedo darte algunos consejos...",
  ui_story_31990601_57_dialog_content = "Por supuesto, sé cómo comer esto. Como dije, soy nativo del Desierto de Rediesel.",
  ui_story_31990601_58_dialog_content = "¡Trago!",
  ui_story_31990601_59_dialog_content = "¡Guau, te lo comiste todo de un bocado! No hay muchas personas que puedan hacer eso por aquí!",
  ui_story_31990601_60_dialog_content = "¡Podrías pasar por una nativa de Rediesel, Señorita Rostro sin Expresión!",
  ui_story_31990601_61_dialog_content = "E-Espera... Realmente no tienes que llegar tan lejos... Solo escúpelo si es demasiado...",
  ui_story_31990601_62_dialog_content = "<size=30>Ella no sabe quién eres, así que deja de fingir ahora...</size>",
  ui_story_31990601_63_dialog_content = "Por favor, deja de hablar. Estoy tratando de disfrutar de mi deliciosa comida...",
  ui_story_31990601_64_dialog_content = "Mmm, sabroso... Urk!",
  ui_story_31990601_65_dialog_content = "¡Qué delicia culinaria... Blegh!",
  ui_story_31990601_66_dialog_content = "L-Lo siento... ¡Pero tu cara está toda roja ahora!",
  ui_story_31990601_67_dialog_content = "Eso es solo porque la comida es tan deliciosa... ¡Hrrng!",
  ui_story_31990601_68_dialog_content = "¿E-Entonces por qué tu cara está empezando a ponerse verde?!",
  ui_story_31990601_69_dialog_content = "E-Eso es solo mi forma de agradecer a la naturaleza por esta maravillosa comida... ¡Ugh!",
  ui_story_31990601_70_dialog_content = "¡Solo dilo, te lo ruego! Tus ojos están empezando a llorar ahora.",
  ui_story_31990601_71_dialog_content = "No puedo desperdiciar algo tan sabroso... ¡Puaj!",
  ui_story_31990601_72_dialog_content = "¡Vaya, no me di cuenta de que nuestra comida era lo suficientemente buena como para hacerte llorar! Si te gusta tanto, ¡quizás puedas ser un Enviado Foodie para el Desierto de Rediesel!",
  ui_story_31990601_73_dialog_content = "¡Tengo mucho aquí! ¡Sírvete tú mismo...!",
  ui_story_31990601_74_dialog_content = "¡E-Espera un segundo!",
  ui_story_31990601_75_dialog_content = "¡Acabo de recordar algo! Nunca compramos un recuerdo para nuestro viaje porque no sabíamos qué conseguir!",
  ui_story_31990601_76_dialog_content = "¿Por qué no llevamos el resto de estas lagartijas de pimienta fantasma a casa como nuestros recuerdos?!",
  ui_story_31990601_77_dialog_content = "Oh, no seas tan educado, simplemente podría dártelos como un regalo.",
  ui_story_31990601_78_dialog_content = "Pero no parece que la Señorita Rostro sin Expresión haya comido hasta saciarse todavía...",
  ui_story_31990601_79_dialog_content = "De hecho, parece que ella quiere otro más!",
  ui_story_31990601_80_dialog_content = "¡P-Por supuesto que ella lo hace! Es solo que...",
  ui_story_31990601_81_dialog_content = "Tenemos un viaje a casa muy largo, y ella podría enfermarse en el camino de regreso si come demasiado.",
  ui_story_31990601_82_dialog_content = "Es por eso...",
  ui_story_31990601_83_dialog_content = "No te preocupes, ¡lo entiendo completamente! Solo asegúrate de contarle a todos sobre nuestra deliciosa comida, ¿de acuerdo?",
  ui_story_31990601_84_dialog_content = "¡Y no olvides darle a Miss Pokerface su parte tampoco! ¡Una dama amable y trabajadora como ella merece solo lo mejor!",
  ui_story_31990601_85_dialog_content = "K... ¿Amable?!",
  ui_story_31990601_86_dialog_content = "Aunque no lo demuestre muy a menudo, mi comida me ayudó a ver qué tipo de persona es realmente ella!",
  ui_story_31990601_87_dialog_content = "Ella va a volver al Coloso contigo, ¿verdad? ¡Espero poder hacerme amigo de ella la próxima vez!",
  ui_story_31990601_88_dialog_content = "E-Estoy seguro de que tendrás tu oportunidad...",
  ui_story_31990601_89_dialog_content = "Bueno, realmente debería irme ahora. ¡Todavía tenemos mucho trabajo que hacer en nuestra cantina!",
  ui_story_31990601_90_dialog_content = "Adiós, PlayerName! Cuida bien de la señorita Pokerface.",
